ght; // shape\u88ab\u7f29\u51cf\u4e3aRectangle\n  }\n  return Math.PI * shape.radius ** 2; // shape\u88ab\u7f29\u51cf\u4e3aCircle\n}\n\n// \u7528\u6237\u81ea\u5b9a\u4e49\u7c7b\u578b\u5b88\u536b\nfunction isString(value: unknown): value is string {\n  return typeof value === 'string';\n}\n\nfunction processUnknown(value: unknown) {\n  if (isString(value)) {\n    console.log(value.length); // value\u88ab\u7f29\u51cf\u4e3astring\n  }\n}\n\n// \u590d\u6742\u7c7b\u578b\u5b88\u536b\ninterface User { name: string; email: string; }\nfunction isUser(obj: unknown): obj is User {\n  return typeof obj === 'object' && \n         obj !== null && \n         'name' in obj && \n         'email' in obj &&\n         typeof (obj as User).name === 'string' &&\n         typeof (obj as User).email === 'string';\n}\n\n// \u65ad\u8a00\u51fd\u6570\uff08assert\u51fd\u6570\uff09\nfunction assertIsNumber(value: unknown): asserts value is number {\n  if (typeof value !== 'number') {\n    throw new Error('Expected number');\n  }\n}\n\nfunction processInput(input: unknown) {\n  assertIsNumber(input);\n  console.log(input.toFixed(2)); // input\u5728\u6b64\u5904\u88ab\u65ad\u8a00\u4e3anumber\n}\n"})}),(0,r.jsx)(e.p,{children:(0,r.jsx)(e.strong,{children:"\u9762\u8bd5\u5b98\u89c6\u89d2:"})}),(0,r.jsx)(e.p,{children:"\u7c7b\u578b\u5b88\u536b\u662fTypeScript\u5b9e\u73b0\u52a8\u6001\u7c7b\u578b\u5b89\u5168\u7684\u6838\u5fc3\u673a\u5236\uff1a"}),(0,r.jsxs)(e.ul,{children:["\n",(0,r.jsxs)(e.li,{children:[(0,r.jsx)(e.strong,{children:"\u8981\u70b9\u6e05\u5355"}),": \u7406\u89e3\u5185\u7f6e\u7c7b\u578b\u5b88\u536b\uff08typeof\u3001instanceof\u3001in\uff09\uff1b\u80fd\u5b9e\u73b0\u81ea\u5b9a\u4e49\u7c7b\u578b\u5b88\u536b\uff1b\u7406\u89e3\u7c7b\u578b\u7f29\u51cf\u673a\u5236\uff1b\u638c\u63e1\u65ad\u8a00\u51fd\u6570"]}),"\n",(0,r.jsxs)(e.li,{children:[(0,r.jsx)(e.strong,{children:"\u52a0\u5206\u9879"}),": \u63d0\u5230\u65ad\u8a00\u51fd\u6570\u4e0e\u7c7b\u578b\u5b88\u536b\u7684\u533a\u522b\uff1b\u5b9e\u73b0\u5